PROGRAM ST260_PALLETERING
VAR
    steg        : INT := 0;
    tmrLyft     : TON;
    trigReset   : R_TRIG;
    xLarm       : BOOL := FALSE;
    xKravOmstart: BOOL := TRUE;
    xAuto       : BOOL := FALSE;
    xHand       : BOOL := FALSE;
    xLyftRor    : BOOL := FALSE;
END_VAR

trigReset(CLK := SYS_RESET);

IF NOT EMG_OK THEN
    xKravOmstart := TRUE;
END_IF;

(* Undertrycket utanfor 40 till 85 kPa nar vakuumet ar pa: antingen har greppet
   slappt eller sa har en sugkopp fastnat mot pallkarmen. *)
IF ST260_VAC_ON AND (ST260_VAC_PRS < 40.0 OR ST260_VAC_PRS > 85.0) THEN
    xLarm := TRUE;
END_IF;

(* Tidsovervakning pa lyftbordet: ett andlage ska nas inom 4,0 s. *)
xLyftRor := ST260_LFT_UP OR ST260_LFT_DOWN;
tmrLyft(IN := xLyftRor, PT := T#4s);
IF tmrLyft.Q THEN
    xLarm := TRUE;
END_IF;

IF trigReset.Q AND EMG_OK AND AIR_OK THEN
    xLarm := FALSE;
    xKravOmstart := FALSE;
END_IF;

SYS_ALARM := xLarm;

(* Lagesvaljaren delar cellen i tva lagen som aldrig far vara aktiva samtidigt. *)
xAuto := EMG_OK AND AIR_OK AND SYS_AUTO AND NOT xLarm AND NOT xKravOmstart;
xHand := EMG_OK AND AIR_OK AND NOT SYS_AUTO AND NOT xLarm AND NOT xKravOmstart;

IF xAuto THEN
    CASE steg OF
        0:
            ST260_LFT_DOWN := FALSE;
            IF ST260_PRT_PRS AND ST260_LAY_CNT < 5 THEN
                ST260_RB_START := TRUE;
                steg := 1;
            END_IF;
        1:
            IF ST260_RB_DONE THEN
                ST260_RB_START := FALSE;
                ST260_VAC_ON := TRUE;
                steg := 2;
            END_IF;
        2:
            IF ST260_VAC_OK THEN
                steg := 3;
            END_IF;
        3:
            (* Ett lager lagt. Sank bordet en lagerhojd. *)
            ST260_VAC_ON := FALSE;
            ST260_LFT_DOWN := TRUE;
            steg := 4;
        4:
            IF ST260_LFT_BOT THEN
                ST260_LFT_DOWN := FALSE;
                steg := 0;
            END_IF;
    ELSE
        steg := 0;
    END_CASE;
ELSE
    ST260_RB_START := FALSE;
    ST260_VAC_ON := FALSE;
    ST260_LFT_DOWN := FALSE;
    steg := 0;
END_IF;

(* Handkorning ar hall-for-att-kora. Knappen slapps, rorelsen slutar i samma
   scan. Den far bara ga uppat, och bara nar automatiken star still. *)
ST260_LFT_UP := xHand AND ST260_MAN_JOG AND NOT ST260_LFT_TOP;

(* Omsesidig uteslutning: bordet kan inte ga at bada hallen. Uppat vinner bara
   for att handkorningen aldrig ar aktiv samtidigt som automatiken. *)
IF ST260_LFT_UP THEN
    ST260_LFT_DOWN := FALSE;
END_IF;
END_PROGRAM

